'use strict';

// MODULES //

var Ajv = require( 'ajv' );
var logger = require( 'debug' );
var schema = require( './schema.json' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:validate-document' );
var opts = {
	'allErrors': true,
	'jsonPointers': true
};
var validate = new Ajv( opts ).compile( schema );


// MAIN //

/**
* Validates a semantic document against the v1 schema.
*
* @private
* @param {Object} document - semantic document
* @returns {Array} validation errors
*/
function validateDocument( document ) {
	debug( 'Validating semantic document against JSON Schema...' );

	// Copy Ajv's mutable `errors` array so callers cannot observe it being replaced by the next validation operation...
	if ( validate( document ) ) {
		debug( 'Semantic document satisfies JSON Schema.' );
		return [];
	}
	debug( 'Semantic document does not satisfy JSON Schema: errors=%d', validate.errors.length );
	return validate.errors.slice();
}


// EXPORTS //

module.exports = validateDocument;
